import pathlib,json,re,hashlib,datetime
R=pathlib.Path.cwd(); D='2026-11-07'
over=json.loads((R/'src/data/i18n/en-overrides.json').read_text(encoding='utf-8-sig'))
reviews=json.loads((R/'docs/editorial/news-reviews.json').read_text(encoding='utf-8-sig'))
items=[]
def article(slug,title,english,description,description_en,pairs,sources,review):
 p=R/f'src/pages/news/{slug}.md'; old=p.read_text(encoding='utf8'); fm=re.split(r'^---\s*$',old,flags=re.M)[1]; fm=fm.split('sources:')[0].strip()
 for key,z,e in [('title',title,english),('description',description,description_en)]:
  fm=re.sub(r'^'+key+r':.*$',key+': '+json.dumps(z,ensure_ascii=False),fm,flags=re.M);over[z]=e
 over[title+'｜環球教育新聞網 Global Education News']=english+' | Global Education News'
 fm=re.sub(r'^updated:.*\n?', '', fm, flags=re.M).strip()
 fm+='\nupdated: "2026-11-07T05:30:00+08:00"\nsources: '+json.dumps([dict(label=l,url=u) for l,u in sources],ensure_ascii=False)
 body=[]
 for z,e in pairs:over[z]=e;body.append(z)
 method='本文於11月7日重查原始文件與獨立資料，保留原發布日並標示實質更新。官方文件用於確認制度與日期，外部觀點另行歸屬；本刊未進行額外訪談，文中的選校與資訊判讀建議為編輯分析。'
 over[method]='This substantive November 7 revision preserves the original publication date. We rechecked primary documents and independent material, separating official rules and dates from attributed outside views. No additional interviews were conducted; recommendations on school choice and interpreting information are editorial analysis.'
 over['資料與報導方法']='Sources and reporting method'
 raw='\n\n'+'\n\n'.join(body)+'\n\n## 資料與報導方法\n\n'+method+'\n'
 p.write_text('---\n'+fm+'\n---'+raw,encoding='utf8')
 checked=re.split(r'^---\s*$',p.read_text(encoding='utf8'),flags=re.M)[2]
 review.update(primarySource=sources[0][1],independentSource=sources[1][1],reviewedAt=D,bodySha256=hashlib.sha256(checked.encode()).hexdigest());reviews[slug]=review
 items.append(dict(slug=slug,path=str(p.relative_to(R)).replace('\\','/'),url=f'https://globalednews.com/news/{slug}/',sources=sources,bodyCjk=len(re.findall('[\u3400-\u9fff]',raw))))

article('uk-student-sponsor-guidance-october-2026','英國學生贊助指引再核對：網頁更新、學校牌照與CAS是三件事','Rechecking UK student sponsorship: publication updates, institutional licences and CAS are different tests','11月6日新增無障礙網頁版本，並非當天全面改制；重新釐清10月指引、動態贊助名冊與學生受影響的不同階段。','The November 6 release adds accessible web versions rather than introducing a wholesale new regime. This revision distinguishes October guidance, the live sponsor register and different stages of student exposure.',[
('英國學生贊助指引在11月6日顯示更新日期，並不代表每位國際學生當天都遇到新規。UKVI的版本紀錄寫明，這次新增的是申請牌照與贊助責任文件的無障礙HTML版本；10月9日才是配合移民規則修訂上述兩份文件的紀錄。本文因此保留10月13日原發布日，重新解釋文件日期與制度生效日的差別，避免家庭把網站改版當作簽證條件突然改變。','A November 6 update date on UK student-sponsor guidance does not mean every international student faced a new rule that day. UKVI’s change log identifies accessible HTML versions of the licensing and sponsorship-duty documents. The October 9 entry records amendments to those two documents following Immigration Rules changes. This revision preserves the original October 13 publication date and distinguishes a publication update from a rule taking effect.'),
('學生贊助制度的核心，是由具備牌照的教育機構承擔特定移民管理責任。官方指引分成申請牌照、贊助責任、合規與高教監管改革四份文件，讀者若只看其中一頁，很容易把學校的義務當成學生新增的申請程序。這也是為何「學校寄來錄取」與「學校可以替這個課程發出CAS」需要分別確認；前者是招生決定，後者連接到學生簽證程序。','Licensed education providers assume specific responsibilities within the immigration system. The official guidance has four documents covering licensing, sponsorship duties, compliance and higher-education regulation. Reading one page in isolation can make an institutional obligation look like a new applicant procedure. An admission offer and the ability to issue a CAS for the relevant course therefore need separate confirmation: they serve different functions.'),
('公開贊助名冊提供的是獲准贊助Student或Child Student路線的機構及類別、評級等資訊。本次查核時，名冊頁面最近更新為11月6日。原文引用外部網站的941家歷史快照，已不足以代表目前可招生名單，因此本次移除該數字，改以官方當期名冊作為查核入口。機構總數即使正確，也無法回答某個申請人、某項課程與某個開學時間是否能取得所需文件。','The public register identifies institutions licensed for the Student or Child Student routes, including relevant categories and ratings. Its latest listed update at our review was November 6. We have removed the earlier article’s third-party snapshot of 941 sponsors because it cannot establish the current list. Even an accurate total would not answer whether a particular applicant, programme and intake can obtain the required documents.'),
('另一個必須分開的概念，是學術品質與移民贊助資格。11月5日HEPI的外部政策分析指出，英格蘭高教監管機關OfS與UKVI各有目的，要求交錯時可能影響招生與學生學習連續性。作者提出加強協調與學生保護的建議，並不是政府已新增的權利。這個觀點提醒家庭：學校仍在教學、課程仍有學術認可，不能單獨證明其贊助狀態沒有變化。','An institution’s academic standing and immigration-sponsorship status are also separate. HEPI’s November 5 analysis argues that England’s OfS and UKVI pursue different purposes and that overlapping requirements can affect recruitment and educational continuity. Its proposals for coordination and student protection are recommendations, not newly enacted rights. Continued teaching or academic recognition alone cannot establish that sponsorship status is unchanged.'),
('官方合規文件也區分調查中移出名冊與最終撤銷牌照。對仍持有效許可的在校生，調查階段並不等同立即失去身分；境外入境許可申請、境內延長申請及已取得簽證但尚未出發者，則有不同處理方式。這些差異說明，不能把某校新聞簡化成「所有人立刻離境」或「所有人都不受影響」。具體通知與個人程序階段，才是判斷後續安排的必要資訊。','Official compliance guidance distinguishes removal from the register during investigation from confirmed licence revocation. Current students with valid permission are not automatically stripped of it during the investigation stage. Overseas entry-clearance applicants, applicants extending permission and visa holders who have not travelled face different provisions. Neither “everyone must leave immediately” nor “nobody is affected” is a reliable summary; individual procedural stage and notices matter.'),
('對台灣準備申請的家庭，編輯建議把三種證據放在同一個時間軸：錄取條件何時完成、CAS由誰在何時正式發出、以及送件時查到哪一版官方名冊。資料間若不一致，應請校方國際學生單位說明適用課程與處理方式，再決定旅行與住宿安排。這不是要求學生自行解讀整套移民法，而是避免用一張舊截圖或招生人員的簡短口頭說明，代替可追溯的書面答覆。','For Taiwanese families, our editorial recommendation is to keep a dated record of offer conditions, the issuing institution and date of the CAS, and the register checked when applying. If those records conflict, seek a course-specific written explanation from the university before committing to travel or accommodation. The purpose is not to make applicants interpret the entire immigration framework, but to replace an old screenshot or brief verbal reassurance with traceable information.'),
('已繳訂金或正在就讀的人，關心的問題則會更接近學習連續性：若招生或贊助受限，誰通知學生、誰協助轉學、已修學分能否銜接，以及費用處理依據是哪份契約。這些問題涉及不同單位，無法從單一名冊欄位推導出答案。本文沒有替任何學校判定財務風險，也不把外部政策報告當成退款承諾；家庭需要的是能對應自己課程與入學年度的正式安排。','For those who have paid a deposit or already enrolled, the questions become educational: who communicates a restriction, supports a transfer, assesses credits and explains the contractual basis for fees? Different offices may be responsible, and a register entry cannot supply all those answers. This article does not assess any institution’s financial risk or treat a policy paper as a refund promise. Students need arrangements that match their own programme and intake.'),
('後續追蹤應回到真正可能改變決策的文件：UKVI的實質修訂紀錄、學校最新CAS說明，以及主管機關針對特定機構的正式通知。每次查看都要記下資料日期，並區分建議、調查與已生效處分。這次修訂移除缺乏當期意義的機構總數，補足制度背景與外部觀點；它沒有宣稱11月6日對台灣學生普遍加收費用，也沒有把任何尚未採行的改革建議寫成現行規定。','The useful next signals are substantive UKVI revisions, current institutional CAS instructions and official notices concerning a named sponsor. Record the date and distinguish proposals, investigations and effective decisions. This revision removes an unhelpful historical institution count and adds context and outside analysis. It does not claim a new universal charge for Taiwanese students on November 6 or present unadopted proposals as current rules.')],
[('UKVI — guidance and dated revision history','https://www.gov.uk/government/publications/student-sponsor-guidance'),('HEPI — independent regulatory analysis, November 5','https://www.hepi.ac.uk/reports/one-sector-two-regulators-the-office-for-students-uk-visas-and-immigration-and-the-challenge-of-regulatory-coherence-in-international-education/'),('UKVI — current sponsor register','https://www.gov.uk/government/publications/register-of-licensed-sponsors-students'),('UKVI — compliance, investigation and sanctions','https://www.gov.uk/government/publications/student-sponsor-guidance/student-sponsor-compliance-accessible')],dict(newsValue='修正讀者可能把11月6日無障礙格式更新誤認新規的問題，並移除無法代表現況的941家快照。',background='交代牌照、招生錄取與CAS不同功能，並說明四份贊助指引之間的制度關係與閱讀順序。',development='對照10月9日實質修訂與11月6日格式發布，分開調查、撤照及個人程序階段。',perspectives='以UKVI正式文件確認制度，再引用HEPI外部分析的教育連續性觀點，不把倡議當政府承諾。',taiwanImpact='將家庭決策落到錄取條件、CAS、名冊時間點與學分費用責任，避免抽象提醒取代實際問題。',uncertainty='不替任何學校判定風險，不推論普遍加費，不保證個案結果；名冊與個別通知仍須當期確認。',independence='HEPI為獨立高教政策分析機構，非UKVI公告轉載；作者制度位置已揭露，規範仍以政府原文為準。'))

article('canada-study-permit-processing-dashboard-2026','加拿大學簽儀表板更新：完成15萬件，不等於核准15萬名學生','Canada’s study-permit dashboard: 150,620 completed applications are not 150,620 approvals','11月7日重查IRCC儀表板，所列統計截止8月31日；補正完成案件定義，並以審計長報告解釋件數、入境與政策效果的差別。','A November 7 recheck finds data through August 31. This revision corrects the meaning of finalized applications and uses the Auditor General’s findings to distinguish case volumes, arrivals and policy outcomes.',[
('加拿大移民部IRCC的申請處理儀表板，在本刊11月7日查核時列出：2026年初至8月31日已完成150,620件新學習許可申請，另有28,440件尚未完成。這是統計截止日期為8月底的工作量快照，不是11月7日當天即時數字。原文的126,230件與37,730件已由新版資料取代；本次同步調整標題，避免舊數字繼續被讀成目前現況。','When checked on November 7, IRCC’s application-processing dashboard reported 150,620 new study-permit applications finalized since January 1 and 28,440 still unfinished, with data through August 31. This is an August snapshot, not a live November 7 count. The current figures replace the earlier article’s 126,230 and 37,730, and the headline has been revised so historical numbers are not mistaken for the latest available snapshot.'),
('「完成」的定義尤其重要。IRCC把核准、拒絕與撤回都列在結案說明內，因此完成件數不能直接當成獲准赴加人數。頁面另指出，這一區的新臨時居留申請不包含延長案件，數字並四捨五入至最接近的5件。把新申請、續簽、簽證核准及實際入境人數放在同一條折線上，看似資訊豐富，實際上會混合不同母體。','Finalized does not mean approved: IRCC’s explanation includes approvals, refusals and withdrawals. This section covers new temporary-residence applications rather than extensions, and values are rounded to the nearest five. Combining new applications, extensions, approvals and actual arrivals in one trend line would mix different populations rather than create a clearer measure of international education.'),
('這也限制了兩個數字之間能做的比較。已完成是年初以來累積的處理量，尚未完成則是在某個時點仍留在系統的案件存量；後者不是同一批申請的失敗數。編輯分析認為，不能用完成件數除以兩者總和，宣稱那就是核准率或辦理成功率。若要談核准率，至少需要同一期間、同一申請類別的核准與拒絕資料，以及清楚說明撤回案件如何處理。','The two figures also measure different things. Finalizations accumulate over the year, while unfinished applications are inventory at a point in time; inventory is not a count of failed applications from the same cohort. Our analysis therefore rejects dividing completed cases by completed plus unfinished cases and calling the result an approval or success rate. A defensible approval rate needs consistent decision categories, period and treatment of withdrawals.'),
('加拿大審計長2026年國際學生計畫改革報告，提供了與行政儀表板不同的檢視角度。稽核認為，2024年起的限制確實降低新學簽核發，但申請減少加上核准率低於預期，使下降幅度超出原先預估，部門未掌握核准率偏低的原因。這是對政策執行與監測的批判，不是證明某位台灣申請者會被拒絕，也不是把所有下降都歸因於單一措施。','The Auditor General’s 2026 audit offers a perspective different from an administrative dashboard. It found that limits introduced in 2024 reduced new permits, but fewer applications and approval rates below projections produced a larger decline than anticipated. The department did not know why approval rates were lower than projected. This critiques implementation and monitoring; it neither predicts a Taiwanese applicant’s outcome nor attributes every decline to one measure.'),
('稽核還發現，改革對較小省份的影響不平均，同時肯定錄取信驗證工具的成效，並指出其他誠信管控仍有缺口。這組正反結果提醒讀者，處理數量、制度完整性與教育機會分布是不同問題。新聞若只用全國總量宣布「加拿大全面變容易」或「全部學校都失去吸引力」，就會抹去地區差異，也忽略報告對行政管理能力提出的具體質疑。','The audit also found disproportionate effects on smaller provinces. It recognized improvements from the acceptance-letter verification tool while identifying weaknesses in other integrity controls. Processing volume, system integrity and the distribution of educational opportunity are distinct questions. National totals cannot justify claims that Canada has become universally easier to enter or that every institution has lost appeal; such claims erase regional differences and the audit’s specific administrative findings.'),
('對正在安排開學的台灣學生，最直接的問題仍是個案進度。IRCC說明，補資料、確認資訊或額外安全查核可能增加時間；秋季與冬季入學也會帶來申請量波動。即使整體待審量下降，某一件申請仍可能需要較長處理。家庭因此應把校方最後報到日、延後入學選項與可退費期限分別記錄，不宜因全國平均印象而提早購買無法更改的行程。','For Taiwanese students preparing to start classes, individual timing remains central. IRCC identifies additional information, verification and security checks as potential causes of delay, with seasonal demand around fall and winter intakes. A falling inventory does not establish how quickly one case will finish. Our practical recommendation is to record the institution’s latest arrival date, deferral options and refund deadlines separately rather than committing to inflexible travel on a national-level impression.'),
('研究所申請者還應辨識一般統計與特定路徑。IRCC研究生入口另有博士申請加速處理資訊，但這不能直接套用到所有碩士、本科或語言課程。本文不把宣傳頁的簡短時間標示寫成無條件保證，也不以儀表板取代個別文件清單。真正可用的準備，是先確認自己課程與申請類別，再循官方入口閱讀完整資格，而不是把別人的快速核准經驗當成自己必然適用的時程。','Graduate applicants should also distinguish general statistics from targeted routes. IRCC has separate information on faster processing for doctoral applicants; that cannot be generalized to every master’s, undergraduate or language programme. A short processing-time statement is not treated here as an unconditional guarantee. Applicants need the official criteria and document requirements for their own category, rather than assuming another person’s fast decision establishes their timeline.'),
('後續應觀察的是資料截止日是否前進、分類口徑是否改變，以及審計建議如何落實。不同期快照可以提示工作量變化，卻不能自行說明變化究竟來自申請減少、處理加速還是其他因素。本次重寫補正撤回也屬結案的定義，保留新申請不含延長的界線，並把官方數字與獨立稽核放在不同證據層級；沒有取得的台灣國籍個別核准率，則不作推估。','Future monitoring should track the data cut-off, any changes in categories and responses to the audit. Successive snapshots may reveal a workload change without showing whether it comes from fewer applications, faster processing or other causes. This revision includes withdrawals in the definition of finalization, preserves the distinction between new applications and extensions, and separates administrative figures from independent audit findings. It does not estimate a Taiwan-specific approval rate that the reviewed data do not provide.')],
[('IRCC — application-processing dashboard, data through August 31','https://www.canada.ca/en/immigration-refugees-citizenship/corporate/reports-statistics/statistics-open-data/immigration-stats/application-processing-system.html'),('Auditor General of Canada — independent audit of student-programme reforms','https://www.canada.ca/content/dam/oag-bvg/audit-reports/documents/ag-202603-international-student-program-reforms.PDF'),('IRCC — graduate-study routes','https://www.canada.ca/en/immigration-refugees-citizenship/services/study-canada/graduate-student.html')],dict(newsValue='原標題數字已被動態儀表板替換，需明示8月31日統計截止而非11月7日即時數字。',background='解釋新申請、延長案件、核准及實際入境母體不同，補正撤回也在已完成定義內。',development='新版150620與28440替換歷史快照，連結2024改革與2026獨立稽核的政策執行觀察。',perspectives='IRCC行政處理說明與審計長的獨立監督並列，呈現錄取信工具成效與誠信管控缺口。',taiwanImpact='連結個案等待、報到日、延後入學及退款安排，博士加速資訊不泛化至所有學生。',uncertainty='不把存量與流量換算核准率，不推估台灣國籍結果，不將工作量變化直接認定為政策因果。',independence='審計長依Auditor General Act獨立稽核IRCC行政執行，並非同部門的公告轉載；兩種資料目的不同。'))

article('new-zealand-years-11-13-final-subjects-first-release-2026','紐西蘭高中課綱分批定稿：2028入學年級、毛利語路徑與未完諮詢要分開看','New Zealand’s senior curriculum rollout: cohorts, Māori-medium pathways and unfinished consultation','首批課綱後，10月21與28日再公布科目，部分項目仍在諮詢；重新解釋2028至2030分年實施，以及環境教育團體對草案的外部檢視。','Further subjects followed the first release on October 21 and 28, while some consultation remained. This revision explains the 2028–2030 cohort transition and an environmental-education group’s review of earlier drafts.',[
('紐西蘭11至13年級新課綱並非在一次公告後就全部完成。教育部首批公布後，10月21日與28日又分別更新科目清單；21日公告更明確表示，少數剩餘科目會隨諮詢與出版程序在今年稍後推出。這使原文「其餘科目10月底前公布」的概括說法需要修正：分批發布確實前進，但不能據此宣布每一科都已定稿或所有學校立即改教新內容。','New Zealand’s senior-secondary curriculum was not completed by a single announcement. Further releases followed on October 21 and 28. The October 21 notice explicitly said a small number of remaining subjects would appear later in the year as consultation and publication were completed. The earlier article’s broad statement that the remaining subjects would arrive by the end of October therefore needs qualification. Progress does not mean every subject is final or every school has already switched.'),
('教育部原始時程把學生世代與資格制度連在一起：2026年就讀Year 9的學生，將在2028年進入Year 11時率先使用更新後高中課綱；Year 12的NZCE預定2029年導入，Year 13的NZACE則在2030年。學校自2027年取得資源、指引與專業學習支持。因此「今年公布」與「學生開始適用」中間有準備期，不能用文件上線日期直接推定目前在校生都換了畢業制度。','The ministry’s initial timetable links the transition to student cohorts. Students in Year 9 in 2026 are due to begin the updated curriculum in Year 11 in 2028. NZCE is scheduled for Year 12 from 2029 and NZACE for Year 13 from 2030, with school resources, guidance and professional learning from 2027. Publication and classroom implementation are separated by preparation; a document appearing online does not establish that all current students have changed qualification systems.'),
('另一個值得注意的發展，是英語與毛利語課程路徑的內容不能混成一張清單。10月21日公告包含首批透過Te Marautanga o Aotearoa發展的最終科目，完整發布後預計提供35個高中科目。這個35描述特定課程路徑的規模，不是全國每一所學校都必須開設35科，也不代表國際學生不用考慮授課語言就能直接選讀。校方實際開課與學生語言準備仍是另一層問題。','The English- and Māori-medium pathways should not be collapsed into one undifferentiated list. The October 21 release included the first final subjects developed through Te Marautanga o Aotearoa, with 35 senior subjects envisaged when fully released. That figure describes a curriculum pathway, not a requirement that every school offer 35 subjects. It also says nothing by itself about an international applicant’s language readiness or a school’s actual provision.'),
('10月28日的後續公告列出歷史、社會科學、藝術、數學、科學與數位科技等多個領域，同時保留未完諮詢的資訊。戶外教育與紐西蘭手語相關諮詢於10月29日截止；Hangarau草案的回饋期限則到11月18日。以本次11月7日查核而言，前一個日期已過，後一項仍在窗口內。發布頁把定稿與諮詢放在一起，不代表兩者具有相同政策狀態。','The October 28 notice covered areas including history, social sciences, arts, mathematics, science and digital technologies, while also listing unfinished consultation. Consultation on specified Outdoor Education and New Zealand Sign Language material closed on October 29; feedback on the Hangarau draft remained open until November 18. At this November 7 review, those dates have different implications. A page containing both final subjects and consultation information does not give them the same status.'),
('外部檢視提供了不只看上線數量的角度。紐西蘭環境教育協會NZAEE在8月更新的分析說明，曾就41份高中科目草案提出回饋，關心永續教育、氣候變遷與學生實際參與是否充分融入。協會認為部分科目較重理論或內容，實作行動與毛利知識的呈現並不平均。這些是該組織依環境教育立場提出的草案評析，不能未經逐科比對就寫成對10月最終版本的結論。','An outside review shifts attention beyond publication counts. In an August update, the New Zealand Association for Environmental Education said it had submitted feedback on 41 subject drafts, examining sustainability, climate education and opportunities for student action. It criticized uneven provision and an emphasis on content or theory in some drafts. These are attributed findings from an environmental-education organization about draft material, not automatically findings about the October final versions.'),
('這也形成後續追蹤的重要問題：最終文件是否回應了公開諮詢的具體意見，以及學校如何把課綱轉化成真正可參與的學習。編輯分析認為，單純計算發布科目數，只能衡量文件進度，不能衡量教學品質。要回答後一個問題，還需要比較草案與定稿內容、教師準備與校內課程安排；本次沒有取得足以判定所有科目已改善的完整對照，因此保留這項不確定性。','The next question is whether final documents respond to specific consultation concerns and how schools translate them into learning opportunities. Our analysis treats subject counts as a measure of document rollout rather than teaching quality. Assessing the latter requires comparisons between drafts and finals, teacher preparation and school-level provision. We did not obtain a comprehensive comparison establishing improvements across every subject, and do not claim one.'),
('對台灣考慮高中留學的家庭，選校時最有用的起點是學生預計進入哪一年級、哪一年入學，再請學校說明適用課綱與資格路徑。若規劃2027年與2028年入學，不能只因差一年就假設同樣課程安排；若中途轉學，也需要釐清既有學習如何銜接。學校宣傳中的「新課綱」應對應到具體選科、評量與升學準備，而不是只有新的證書名稱。','Taiwanese families considering secondary study should start with the intended year group and entry year, then ask the school which curriculum and qualification pathway applies. Entry in 2027 and 2028 should not be assumed to produce identical arrangements, and transfers require a clear explanation of how previous learning connects. Recruitment references to a new curriculum need to translate into actual subject choices, assessment and preparation for further study, rather than a new certificate name alone.'),
('大學入學銜接與特定學校開課，仍須由後續正式資訊確認。本文不把政府課綱的全國規劃當成每所學校的開課保證，也不把NZAEE對草案的批評說成改革必定失敗。修訂的目的，是把公布、諮詢、教師準備、分年實施與學生個別路徑放回各自時間點。接下來應追蹤剩餘科目定稿、實施支持及校方課程手冊，才能判斷一個家庭真正需要改變哪些準備。','University-entry arrangements and a particular school’s offerings still require the relevant formal information. A national curriculum plan is not a guarantee that each school will run every subject, and NZAEE’s draft critique does not establish that reform will fail. This revision separates publication, consultation, teacher preparation, phased implementation and individual pathways. Remaining final subjects, implementation support and school course handbooks are the next evidence needed for practical planning.')],
[('Ministry of Education — initial senior subject release and implementation','https://www.education.govt.nz/news/first-release-years-tau-11-13-subjects'),('NZAEE — independent analysis of 41 subject drafts, updated August 9','https://www.nzaee.org.nz/news-and-publications/phase-5-senior-secondary-curriculum-consultation'),('Ministry of Education — October 21 release and remaining consultation','https://www.education.govt.nz/news/more-senior-secondary-subjects-now-available-tahurangi'),('Ministry of Education — October 28 subject release','https://www.education.govt.nz/news/more-senior-curriculum-subjects-released')],dict(newsValue='更正原稿把其餘課綱一概視為10月底完成的簡化，補上10月21與28日分批公告及仍在諮詢項目。',background='交代2026年Year9世代、2027教師準備及2028至2030分年課綱與資格導入關係。',development='區分最終科目、剩餘草案與不同回饋期限，說明35科屬毛利語路徑而非每校必開科目。',perspectives='教育部發布與NZAEE環境教育角度並列，外部分析是8月草案評論，不冒充最終版逐科審核。',taiwanImpact='以入學年度與年級連結選科、轉學與學習銜接，要求校方具體課程安排而非只看證書改名。',uncertainty='不保證學校全數開課，不判斷所有草案問題已改善，不把課綱公告當大學入學銜接已完整確定。',independence='NZAEE為外部環境教育組織，提出自行審查41科草案的方法與立場，非教育部公告轉載。'))

for path,obj in [('src/data/i18n/en-overrides.json',over),('docs/editorial/news-reviews.json',reviews),('docs/daily-checks/2026-11-07/archive-prepared.json',items)]:
 (R/path).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
